export interface StarCatalogue {
  /** Right ascension, radians. */
  ra: Float32Array;
  /** Declination, radians. */
  dec: Float32Array;
  /** Visual magnitude. */
  mag: Float32Array;
  /** Johnson B-V colour index. */
  bv: Float32Array;
}

let cache: StarCatalogue | null = null;

/** Decodes the packed catalogue once and memoises the result. */
export function starCatalogue(): StarCatalogue {
  if (cache) return cache;
  const bin = atob(PACKED);
  const n = (bin.length / 6) | 0;
  const ra = new Float32Array(n);
  const dec = new Float32Array(n);
  const mag = new Float32Array(n);
  const bv = new Float32Array(n);
  const DEG = Math.PI / 180;
  for (let i = 0; i < n; i++) {
    const o = i * 6;
    const rRaw = bin.charCodeAt(o) | (bin.charCodeAt(o + 1) << 8);
    const dRaw = bin.charCodeAt(o + 2) | (bin.charCodeAt(o + 3) << 8);
    ra[i] = (rRaw / 65535) * 360 * DEG;
    dec[i] = ((dRaw / 65535) * 180 - 90) * DEG;
    mag[i] = (bin.charCodeAt(o + 4) / 255) * 8.5 - 1.5;
    bv[i] = (bin.charCodeAt(o + 5) / 255) * 2.6 - 0.4;
  }
  cache = { ra, dec, mag, bv };
  return cache;
}
